node --input-type=module -e "
import Ajv from 'ajv';
const ajv = new Ajv({strict: false, validateFormats: false});
// 1. uncompilable schema
try {
  ajv.compile({type: 'object', properties: {location: {type: 'not-a-json-schema-type'}}});
  console.log('BAD-SCHEMA: compiled without throwing');
} catch (e) {
  console.log('BAD-SCHEMA throws:', e.message);
}
// 2. missing required
const v1 = ajv.compile({type: 'object', properties: {location: {type: 'string'}}, required: ['location']});
console.log('missing:', JSON.stringify(v1.errors));
// 3. wrong type
const v2 = ajv.compile({type: 'object', properties: {ssn: {type: 'string'}}, required: ['ssn']});
const ok2 = v2({ssn: 123456789});
console.log('wrongtype ok=', ok2, JSON.stringify(v2.errors));
// 4. enum
const v3 = ajv.compile({type: 'object', properties: {unit: {type: 'string', enum: ['C','F']}}, required: ['unit']});
const ok3 = v3({unit: 'Kelvin'});
console.log('enum ok=', ok3, JSON.stringify(v3.errors));
// 5. extra props passthrough + no coercion
const v4 = ajv.compile({type: 'object', properties: {a: {type: 'string'}}});
const input = {a: 'x', extra: {deep: true}};
const ok4 = v4(input);
console.log('extra ok=', ok4, 'input unchanged:', JSON.stringify(input) === JSON.stringify({a:'x',extra:{deep:true}}));
"

